// AddInterval returns t moved forward by one billing interval: a month or a year.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	if iv == store.Yearly {
		return t.AddDate(1, 0, 0)
	}
	return t.AddDate(0, 1, 0)
}

args.new_string:
// Anchor is the start of a subscription's first paid period, which its billing periods are counted from: the end of its
// trial when it has one, otherwise its start.
func Anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return sub.TrialEnd.UTC()
	}
	return sub.StartedAt.UTC()
}

// PeriodStart returns the start of period n (n = 0, 1, 2, ...) of a subscription anchored at anchor: n months (or years)
// after the anchor, on the anchor's day of the month and at its time of day, in UTC. When that month is shorter than the
// anchor's day, the period starts on the month's last day. Each period is counted from the anchor, so a short month does
// not move later periods.
func PeriodStart(anchor time.Time, iv store.Interval, n int) time.Time {
	anchor = anchor.UTC()
	months := n
	if iv == store.Yearly {
		months = 12 * n
	}
	total := int(anchor.Month()) - 1 + months
	year, month := anchor.Year()+total/12, time.Month(total%12+1)
	day := min(anchor.Day(), daysIn(year, month))
	return time.Date(year, month, day, anchor.Hour(), anchor.Minute(), anchor.Second(), anchor.Nanosecond(), time.UTC)
}

// PeriodEndAfter returns the first period boundary of a subscription anchored at anchor that is after t. For t at the
// start of a period, that is the period's end; for any other t, it is the end of the period that contains t.
func PeriodEndAfter(anchor time.Time, iv store.Interval, t time.Time) time.Time {
	for n := 0; ; n++ {
		if b := PeriodStart(anchor, iv, n); b.After(t) {
			return b
		}
	}
}

// AddInterval returns t moved forward by one billing interval: a month or a year, clamped to the last day of a shorter
// month. Use PeriodStart to compute later periods of a subscription, which keeps its anchor's day.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	return PeriodStart(t, iv, 1)
}

func daysIn(year int, month time.Month) int {
	return time.Date(year, month+1, 0, 0, 0, 0, 0, time.UTC).Day()
}

