// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription that is several
// periods behind is renewed once for each period that has ended, in order. A subscription set to cancel at the end of its
// period is canceled. Otherwise its next period starts where the ended one did and is invoiced: a licensed plan bills the
// new period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription
// past due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

// renew brings a subscription up to date as of now, one period at a time, so that the renewal does not depend on when the
// job runs.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	anchor := billing.Anchor(sub)
	for !sub.CurrentPeriodEnd.After(now) && sub.Status != store.Canceled {
		var err error
		if sub, err = s.renewPeriod(ctx, sub, plan, anchor); err != nil {
			return err
		}
	}
	return nil
}

// renewPeriod renews a subscription whose current period has ended: it cancels the subscription when it is set to cancel at
// the period's end; otherwise it starts the next period, invoices it, and returns the subscription with that period.
func (s *Service) renewPeriod(ctx context.Context, sub store.Subscription, plan store.Plan, anchor time.Time) (store.Subscription, error) {
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return sub, err
	}
	start := sub.CurrentPeriodEnd
	end := billing.PeriodEndAfter(anchor, plan.Interval, start)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return sub, err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return sub, err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return sub, nil
}

