func TestMonthEndAnchorDoesNotDrift(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.Clock.Set(time.Date(2026, time.January, 31, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	ends := []time.Time{
		time.Date(2026, time.February, 28, 10, 0, 0, 0, time.UTC),
		time.Date(2026, time.March, 31, 10, 0, 0, 0, time.UTC),
		time.Date(2026, time.April, 30, 10, 0, 0, 0, time.UTC),
		time.Date(2026, time.May, 31, 10, 0, 0, 0, time.UTC),
	}
	for _, end := range ends {
		e.Clock.Set(sub.CurrentPeriodEnd)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue = %d, %v", n, err)
		}
		sub, _ = e.Store.Subscription(e.Acme.ID, sub.ID)
		if !sub.CurrentPeriodEnd.Equal(end) {
			t.Fatalf("period ends %v, want %v", sub.CurrentPeriodEnd, end)
		}
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != len(ends)+1 {
		t.Fatalf("invoices = %d, want %d", len(invs), len(ends)+1)
	}
}

func TestLateRenewalInvoicesEachMissedPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.Clock.Set(time.Date(2026, time.January, 31, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The job did not run for two months: the periods from Feb 28 and from Mar 31 have both ended by Apr 2.
	e.Clock.Set(time.Date(2026, time.April, 2, 10, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, time.March, 31, 10, 0, 0, 0, time.UTC)) ||
		!got.CurrentPeriodEnd.Equal(time.Date(2026, time.April, 30, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("after the catch-up = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	starts := map[time.Time]bool{}
	for _, inv := range invs {
		if inv.PeriodStart != nil {
			starts[*inv.PeriodStart] = true
		}
	}
	for _, want := range []time.Time{
		time.Date(2026, time.January, 31, 10, 0, 0, 0, time.UTC),
		time.Date(2026, time.February, 28, 10, 0, 0, 0, time.UTC),
		time.Date(2026, time.March, 31, 10, 0, 0, 0, time.UTC),
	} {
		if !starts[want] {
			t.Errorf("no invoice for the period starting %v; invoices = %+v", want, invs)
		}
	}
	if len(invs) != 3 {
		t.Fatalf("invoices = %d, want one per period (3)", len(invs))
	}
}

