func utc(y int, m time.Month, d, hh, mm int) time.Time {
	return time.Date(y, m, d, hh, mm, 0, 0, time.UTC)
}

func TestPeriodStartKeepsTheAnchorDay(t *testing.T) {
	anchor := utc(2026, time.January, 31, 9, 30)
	want := []time.Time{
		utc(2026, time.January, 31, 9, 30),
		utc(2026, time.February, 28, 9, 30),
		utc(2026, time.March, 31, 9, 30),
		utc(2026, time.April, 30, 9, 30),
		utc(2026, time.May, 31, 9, 30),
		utc(2026, time.June, 30, 9, 30),
		utc(2026, time.July, 31, 9, 30),
	}
	for n, w := range want {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("monthly period %d = %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartLeapDayAnchor(t *testing.T) {
	anchor := utc(2028, time.February, 29, 0, 0)
	for _, tc := range []struct {
		n    int
		want time.Time
	}{
		{1, utc(2029, time.February, 28, 0, 0)},
		{2, utc(2030, time.February, 28, 0, 0)},
		{3, utc(2031, time.February, 28, 0, 0)},
		{4, utc(2032, time.February, 29, 0, 0)},
	} {
		if got := PeriodStart(anchor, store.Yearly, tc.n); !got.Equal(tc.want) {
			t.Errorf("yearly period %d = %v, want %v", tc.n, got, tc.want)
		}
	}
	if got := PeriodStart(anchor, store.Monthly, 1); !got.Equal(utc(2028, time.March, 29, 0, 0)) {
		t.Errorf("monthly period 1 = %v", got)
	}
}

func TestPeriodStartKeepsTimeOfDayInUTC(t *testing.T) {
	anchor := time.Date(2026, time.August, 31, 23, 15, 7, 5, time.FixedZone("CET", 3600))
	got := PeriodStart(anchor, store.Monthly, 1)
	if want := time.Date(2026, time.September, 30, 22, 15, 7, 5, time.UTC); !got.Equal(want) || got.Location() != time.UTC {
		t.Fatalf("PeriodStart = %v, want %v in UTC", got, want)
	}
}

func TestPeriodEndAfter(t *testing.T) {
	anchor := utc(2026, time.January, 31, 9, 0)
	if got := PeriodEndAfter(anchor, store.Monthly, utc(2026, time.February, 28, 9, 0)); !got.Equal(utc(2026, time.March, 31, 9, 0)) {
		t.Errorf("end at a boundary = %v", got)
	}
	if got := PeriodEndAfter(anchor, store.Monthly, utc(2026, time.March, 3, 0, 0)); !got.Equal(utc(2026, time.March, 31, 9, 0)) {
		t.Errorf("end inside a period = %v", got)
	}
	if got := PeriodEndAfter(anchor, store.Monthly, utc(2026, time.January, 1, 0, 0)); !got.Equal(anchor) {
		t.Errorf("end before the anchor = %v", got)
	}
}

func TestAnchor(t *testing.T) {
	started := utc(2026, time.January, 31, 9, 0)
	trialEnd := utc(2026, time.February, 14, 9, 0)
	if got := Anchor(store.Subscription{StartedAt: started}); !got.Equal(started) {
		t.Errorf("without a trial = %v", got)
	}
	if got := Anchor(store.Subscription{StartedAt: started, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
		t.Errorf("with a trial = %v", got)
	}
}

func TestAddIntervalClampsToShortMonth(t *testing.T) {
	if got := AddInterval(utc(2026, time.January, 31, 9, 0), store.Monthly); !got.Equal(utc(2026, time.February, 28, 9, 0)) {
		t.Errorf("monthly from Jan 31 = %v", got)
	}
}
