1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
69			if err != nil {
70				return sub, err
71			}
72			if !paid {
73				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
74					return sub, err
75				}
76			}
77		}
78		return sub, nil
79	}
80	
81	// UpdateInput changes a subscription; nil fields stay as they are.
82	type UpdateInput struct {
83		PlanID   *string
84		Quantity *int
85	}
86	
87	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
88	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
89		if in.PlanID != nil {
90			p, ok := s.Store.Plan(orgID, *in.PlanID)
91			if !ok {
92				return store.Subscription{}, store.ErrNotFound
93			}
94			if !p.Active {
95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription that is several
144	// periods behind is renewed once for each period that has ended, in order. A subscription set to cancel at the end of its
145	// period is canceled. Otherwise its next period starts where the ended one did and is invoiced: a licensed plan bills the
146	// new period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription
147	// past due. RenewDue returns how many subscriptions it renewed or canceled.
148	func (s *Service) RenewDue(ctx context.Context) (int, error) {
149		now := s.Clock.Now()
150		n := 0
151		for _, sub := range s.Store.DueSubscriptions(now) {
152			if err := ctx.Err(); err != nil {
153				return n, err
154			}
155			if err := s.renew(ctx, sub, now); err != nil {
156				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
157			}
158			n++
159		}
160		return n, nil
161	}
162	
163	// renew brings a subscription up to date as of now, one period at a time, so that the renewal does not depend on when the
164	// job runs.
165	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
166		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
167		if !ok {
168			return store.ErrNotFound
169		}
170		anchor := billing.Anchor(sub)
171		for !sub.CurrentPeriodEnd.After(now) && sub.Status != store.Canceled {
172			var err error
173			if sub, err = s.renewPeriod(ctx, sub, plan, anchor); err != nil {
174				return err
175			}
176		}
177		return nil
178	}
179	
180	// renewPeriod renews a subscription whose current period has ended: it cancels the subscription when it is set to cancel at
181	// the period's end; otherwise it starts the next period, invoices it, and returns the subscription with that period.
182	func (s *Service) renewPeriod(ctx context.Context, sub store.Subscription, plan store.Plan, anchor time.Time) (store.Subscription, error) {
183		if sub.CancelAtPeriodEnd {
184			end := sub.CurrentPeriodEnd
185			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
186				x.Status, x.CanceledAt = store.Canceled, &end
187				return nil
188			})
189			if err == nil {
190				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
191			}
192			return sub, err
193		}
194		start := sub.CurrentPeriodEnd
195		end := billing.PeriodEndAfter(anchor, plan.Interval, start)
196		paid := true
197		var err error
198		switch {
199		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
200			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
201		case plan.UsageType == store.Licensed:
202			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
203		}
204		if err != nil {
205			return sub, err
206		}
207		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
208			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
209			if paid {
210				x.Status = store.Active
211			} else {
212				x.Status = store.PastDue
213			}
214			return nil
215		})
216		if err != nil {
217			return sub, err
218		}
219		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
220		return sub, nil
221	}
222	
223	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
224	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
225	// payment method stays open and counts as paid here (it is paid by hand).
226	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
227		var lines []store.Line
228		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
229		switch plan.UsageType {
230		case store.Licensed:
231			if plan.UnitAmount > 0 {
232				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
233			}
234		case store.Metered:
235			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
236				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
237			}
238		}
239		ps, pe := start, end
240		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
241			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
242		if err != nil {
243			return false, err
244		}
245		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
246		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
247		var decline *payments.DeclineError
248		switch {
249		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
250			return true, nil
251		case errors.As(err, &decline):
252			return false, nil
253		default:
254			return false, err
255		}
256	}
257	
258	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
259		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
260			x.Status = st
261			return nil
262		})
263		if err == nil {
264			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
265		}
266		return sub, err
267	}
268	
269	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
270		if s.Publisher != nil {
271			_ = s.Publisher.Publish(ctx, orgID, typ, data)
272		}
273	}
