258	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
259		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
260			x.Status = st
261			return nil
262		})
263		if err == nil {
264			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
265		}
266		return sub, err
267	}
268	
269	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
270		if s.Publisher != nil {
271			_ = s.Publisher.Publish(ctx, orgID, typ, data)
272		}
273	}
